#include <stdio.h>

int aray[103];
int res[102];

int main(int argc, char *argv[])
{
    int n, i, first_multi = -1, first_other = -1, last_one = -1;
    int three = 0, zero = 0;

    scanf("%d", &n);
    for (i = 0; i < 101; i++) {
        res[i] = -2;
    }

    for (i = 0; i < n; i++) {
        scanf("%d", &aray[i]);
        if (aray[i] == 100) {
            three++;
        } else if (aray[i] == 0) {
            zero++;
        } else if (aray[i] > 9 && aray[i] < 100) {
            if (aray[i] % 10 == 0) {
                if (first_multi == -1) first_multi = aray[i];
            } else {
                if (first_other == -1) first_other = aray[i];
            }
        } else { /* 1..9 */
            last_one = aray[i];
        }
    }

    int size = 0;

    if (n == 1) {
        res[size++] = aray[0];
    } else if (three > 0) {
        res[size++] = 100;
        if (first_multi != -1) res[size++] = first_multi;
        if (last_one != -1) res[size++] = last_one;
        if (zero > 0) res[size++] = 0;
    } else {
        if (last_one != -1) {
            if (first_multi != -1) res[size++] = first_multi;
            res[size++] = last_one;
            if (zero > 0) res[size++] = 0;
        } else {
            if (first_multi != -1) {
                res[size++] = first_multi;
            } else if (first_other != -1) {
                res[size++] = first_other;
            }
            if (zero > 0) res[size++] = 0;
        }
    }

    printf("%d\n", size);
    for (i = 0; i < size; i++) {
        printf("%d ", res[i]);
    }
    printf("\n");
    return 0;
}

